export function PlateRemark(prop: HoverRemarkProp) {
  return (
    <HoverRemark {...prop}>
      アイロンビーズの作業台のこと。<br/>
      公式情報によると「ビーズプレート」という呼び方は日本で使われる通称であり、正式には「ペグボード」と呼ぶそうですが、ここでは「ビーズプレート」と記載します。<br/>
      <Image src={plate} w='10em' aspectRatio='184 / 159' loading='lazy' />
      <br/>
      <Remarks mark='※'>
        プレートには大きく次の２種類があります。<br/>
        <List.Root>
          <List.Item>四角形プレート<SquarePlateRemark withinPortal /></List.Item>
          <List.Item>六角形プレート<HexagonPlateRemark withinPortal /></List.Item>
        </List.Root>
      </Remarks>
    </HoverRemark>
  )
}

export function SquarePlateRemark(prop: HoverRemarkProp) {
  return (
    <HoverRemark {...prop}>
      下図のように、ビーズを四角形に並べていけるアイロンビーズの作業台のこと。<br/>
      <Image src={squarePlate} w='10em' aspectRatio='291 / 218' loading='lazy' />
      <br/>
      <Remarks mark='※'>
        上図のように１点から順番に外へ並べていった際に、四角形を描くビーズ配置のプレートを、ここでは"四角型プレート"と記載しています。<br/>
        プレート自体の形がハート型なモノもありますが、ここでは"四角型プレート"のビーズ配置に分類されます。
      </Remarks>
    </HoverRemark>
  )
}

export function HexagonPlateRemark(prop: HoverRemarkProp) {
  return (
    <HoverRemark {...prop}>
      下図のように、ビーズを六角形に並べていけるアイロンビーズの作業台のこと。<br/>
      <Image src={hexagonPlate} w='10em' aspectRatio='291 / 218' loading='lazy' />
      <br/>
      <Remarks mark='※'>
        上図のように１点から順番に外へ並べていった際に、六角形を描くビーズ配置のプレートを、ここでは"六角型プレート"と記載しています。<br/>
        プレート自体の形が円型、星型なモノもありますが、ここでは"六角型プレート"のビーズ配置に分類されます。
      </Remarks>
    </HoverRemark>
  )
}

export function InterlockingBlocksToyRemark(prop: HoverRemarkProp) {
  return (
    <HoverRemark {...prop}>
      インターロッキングビルディングブロックの知育オモチャの１つで、私も子供の頃に遊んだ記憶があります。<br/>
      時代と共にデザインや機能が豊富になっていますがコンセプトは同じで、 "凹凸のあるパネル" 同士を組み合わせて、色々なモノを作っていくスタイルです。
    </HoverRemark>
  )
}

export function AssociationGameRemark(prop: HoverRemarkProp) {
  return (
    <ReferIntoroRemarkFrame {...prop}>
      <AssociationGame />
    </ReferIntoroRemarkFrame>
  )
}

export function AssociationGame() {
  return (
    <>
      まず頭を空っぽにして、作った立体アイロンビーズのどこか一部分に注目します。(作業工程の一部分でも大丈夫)<br/>
      それを見て、「植物の茎の一部に見える」「帽子に見える」と連想するゲーム。<br/>
      結局はアイロンビーズなので、本来まったく身の周りのモノと関係ないのですが、"形"や"動き"という点だけに着目して「似てる」と結びつける遊びです。<br/>
      その後、その結びつけたイメージをアイロンビーズで作っていきます。<br/>
    </>
  )
}


